package com.example.reporting

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import javax.script.ScriptEngineManager
import java.io.StringWriter

fun main() {
    embeddedServer(Netty, port = 8080) {
        module()
    }.start(wait = true)
}

fun Application.module() {
    routing {
        post("/api/v2/reports/generate") {
            val params = call.receiveParameters()
            val templateExpr = params["filter_expression"] ?: ""
            val dataSource = params["datasource"] ?: "default"
            val format = params["output_format"] ?: "json"

            // Validate output format
            if (format !in listOf("json", "csv", "xml")) {
                call.respondText("Invalid format", status = io.ktor.http.HttpStatusCode.BadRequest)
                return@post
            }

            // Validate datasource name (alphanumeric only)
            if (!dataSource.matches(Regex("^[a-zA-Z0-9_]+$"))) {
                call.respondText("Invalid datasource", status = io.ktor.http.HttpStatusCode.BadRequest)
                return@post
            }

            // Process the filter expression through the template engine
            val result = evaluateFilterExpression(templateExpr, dataSource)
            call.respondText(result, status = io.ktor.http.HttpStatusCode.OK)
        }

        get("/health") {
            call.respondText("OK")
        }

        post("/api/v2/reports/schedule") {
            val params = call.receiveParameters()
            val cronExpr = params["cron"] ?: "0 0 * * *"
            val reportId = params["report_id"] ?: ""
            // Schedule logic (stub)
            call.respondText("{\"scheduled\": true, \"report_id\": \"$reportId\"}")
        }
    }
}

fun evaluateFilterExpression(expression: String, dataSource: String): String {
    if (expression.isBlank()) {
        return "{\"data\": [], \"source\": \"$dataSource\"}"
    }

    // Use Kotlin scripting engine to evaluate dynamic filter expressions
    // This allows complex predicates like "amount > 1000 && status == 'active'"
    val engine = ScriptEngineManager().getEngineByExtension("kts")
        ?: ScriptEngineManager().getEngineByName("kotlin")
        ?: throw RuntimeException("Kotlin script engine not available")

    val writer = StringWriter()
    engine.context.writer = writer

    return try {
        // Bind the datasource context
        engine.put("__datasource", dataSource)
        engine.put("__records", getSampleRecords(dataSource))

        // Build the evaluation script
        val script = """
            val records = bindings["__records"] as List<Map<String, Any>>
            val filtered = records.filter { record ->
                $expression
            }
            filtered.joinToString(",") { it.toString() }
        """.trimIndent()

        val result = engine.eval(script)
        "{\"data\": [${result ?: ""}], \"source\": \"$dataSource\", \"filter\": \"applied\"}"
    } catch (e: Exception) {
        "{\"error\": \"Filter evaluation failed: ${e.message?.take(100)}\"}"
    }
}

fun getSampleRecords(dataSource: String): List<Map<String, Any>> {
    // In production, this queries the actual datasource
    return listOf(
        mapOf("id" to 1, "amount" to 1500, "status" to "active"),
        mapOf("id" to 2, "amount" to 300, "status" to "inactive"),
        mapOf("id" to 3, "amount" to 2200, "status" to "active")
    )
}
